The supplied files are empty implementations, so I added the standard meetup API:

- `Weekday` and `Schedule` enums.
- `scheduler` class with a constructor accepting year and month.
- `meetup` method returning the matching `std::chrono::year_month_day`.
- Support for first, second, third, fourth, last, and teenth occurrences.

meetup.h
```
#if !defined(MEETUP_H)
#define MEETUP_H

#include <chrono>

namespace meetup {

enum class Weekday {
    Sunday,
    Monday,
    Tuesday,
    Wednesday,
    Thursday,
    Friday,
    Saturday
};

enum class Schedule {
    First,
    Second,
    Third,
    Fourth,
    Last,
    Teenth
};

class scheduler {
public:
    scheduler(int year, int month);

    std::chrono::year_month_day meetup(Weekday weekday,
                                       Schedule schedule) const;

private:
    std::chrono::year_month month_;
};

}  // namespace meetup

#endif  // MEETUP_H
```

