#include "meetup.h"

namespace meetup {
namespace {

int weekday_value(Weekday weekday)
{
    return static_cast<int>(weekday);
}

int offset_to_weekday(int first_weekday, int target_weekday)
{
    return (target_weekday - first_weekday + 7) % 7;
}

}  // namespace

scheduler::scheduler(int year, int month)
    : month_(std::chrono::year{year} / std::chrono::month{static_cast<unsigned>(month)})
{
}

std::chrono::year_month_day scheduler::meetup(Weekday weekday,
                                              Schedule schedule) const
{
    using namespace std::chrono;

    const auto first_day = year_month_day{month_ / day{1}};
    const auto first_weekday =
        weekday{sys_days{first_day}}.c_encoding();
    const auto target_weekday = weekday_value(weekday);

    unsigned day_of_month = 1;

    switch (schedule) {
    case Schedule::First:
    case Schedule::Second:
    case Schedule::Third:
    case Schedule::Fourth: {
        const auto occurrence = static_cast<int>(schedule) + 1;
        day_of_month = static_cast<unsigned>(
            1 + offset_to_weekday(first_weekday, target_weekday) +
            (occurrence - 1) * 7);
        break;
    }

    case Schedule::Teenth: {
        const auto thirteenth = year_month_day{month_ / day{13}};
        const auto thirteenth_weekday =
            weekday{sys_days{thirteenth}}.c_encoding();

        day_of_month = static_cast<unsigned>(
            13 + offset_to_weekday(thirteenth_weekday, target_weekday));
        break;
    }

    case Schedule::Last: {
        const auto last_day =
            year_month_day_last{month_ / day_last};
        const auto last_weekday =
            weekday{sys_days{last_day}}.c_encoding();

        const auto difference =
            (last_weekday - target_weekday + 7) % 7;

        day_of_month = static_cast<unsigned>(
            static_cast<unsigned>(last_day.day()) - difference);
        break;
    }
    }

    return year_month_day{month_ / day{day_of_month}};
}

}  // namespace meetup
